package org.simpleweather.qa;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;import java.lang.reflect.*;import java.io.*;import java.util.concurrent.atomic.*;import java.util.function.*;
/** Interactions specific to the pre-3.0.0-3 changes, against installed production classes. */
public final class Pre3UpdateUiTests extends Instrumentation {
 Activity host,music;Dialog search;ClassLoader loader;int checks;Bundle args;
 public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 Object field(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 Object call(Object o,String name,Class<?>[] types,Object...v)throws Exception{Method m=(o instanceof Class?(Class<?>)o:o.getClass()).getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(o instanceof Class?null:o,v);}
 void ui(Runnable r){AtomicReference<Throwable> e=new AtomicReference<>();runOnMainSync(()->{try{r.run();}catch(Throwable x){e.set(x);}});if(e.get()!=null)throw new RuntimeException(e.get());waitForIdleSync();}
 void check(boolean b,String message){if(!b)throw new AssertionError(message);checks++;}
 void collect(View v,List<View> out){out.add(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)collect(((ViewGroup)v).getChildAt(i),out);}
 List<View> views(View v){List<View> out=new ArrayList<>();collect(v,out);return out;}
 TextView button(View root,String label){for(View v:views(root))if(v instanceof TextView&&label.equals(((TextView)v).getText().toString()))return (TextView)v;throw new AssertionError("Missing button "+label);}
 String t(Context c,String key){int id=c.getResources().getIdentifier(key,"string",c.getPackageName());if(id==0)id=c.getResources().getIdentifier(key,"string","org.simpleweather.module.music");return c.getString(id);}
 void pause()throws Exception{Thread.sleep(300);waitForIdleSync();}
 public void onStart(){Bundle result=new Bundle();try{
  Context c=getTargetContext();String lang=args.getString("language","zh-CN");c.getSharedPreferences("toolbox",0).edit().putString("app_language",lang).putInt("seen_version",54).commit();loader=c.getClassLoader();
  host=startActivitySync(new Intent().setClassName(c,"org.simpleweather.app.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();Object apps=field(host,"apps");
  for(String id:new String[]{"music","todo"})try(InputStream in=new FileInputStream("/data/local/tmp/internal-apps/"+id+".ddapp")){call(apps,"install",new Class[]{InputStream.class,String.class,String.class},in,id,null);}
  ui(()->{try{call(host,"switchTab",new Class[]{int.class},-2);}catch(Exception e){throw new RuntimeException(e);}});pause();ScrollView scroll=(ScrollView)field(host,"pageScroll");ui(()->scroll.scrollTo(0,850));pause();int old=scroll.getScrollY();check(old>150,"store is scrolled before installation update");Object body=field(host,"body");ui(()->{try{call(host,"installedAppsChanged",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});pause();check(field(host,"pageScroll")==scroll&&field(host,"body")==body,"store view kept after install");check(Math.abs(scroll.getScrollY()-old)<=4,"store scroll retained after install");
  Intent intent=(Intent)Class.forName("org.simpleweather.app.ModuleRuntime",true,loader).getMethod("pageIntent",Context.class,String.class,String.class).invoke(null,host,"music","main");music=startActivitySync(intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();Object page=field(music,"page");ClassLoader cl=page.getClass().getClassLoader();Class<?> track=Class.forName("org.daidai.modules.music.MusicLibrary$Track",true,cl);Constructor<?> constructor=track.getConstructor(String.class,String.class);
  List<Object> tracks=new ArrayList<>();tracks.add(constructor.newInstance("content://qa/1","Alpha one"));tracks.add(constructor.newInstance("content://qa/2","Alpha two"));tracks.add(constructor.newInstance("content://qa/3","Beta"));Set<String> selected=new LinkedHashSet<>();selected.add("previous");AtomicInteger edited=new AtomicInteger(),returned=new AtomicInteger();Class<?> editorType=Class.forName("org.daidai.modules.music.MusicSearchScreen$TrackEditor",true,cl);
  Object editor=Proxy.newProxyInstance(cl,new Class[]{editorType},(o,m,v)->{if(m.getName().equals("open")){edited.incrementAndGet();tracks.set(0,constructor.newInstance("content://qa/1","Gamma"));((Runnable)v[1]).run();}return null;});Class<?> searchType=Class.forName("org.daidai.modules.music.MusicSearchScreen",true,cl);ui(()->{try{search=(Dialog)searchType.getMethod("open",Activity.class,Supplier.class,Set.class,editorType,Runnable.class).invoke(null,music,(Supplier<List<Object>>)()->tracks,selected,editor,(Runnable)returned::incrementAndGet);}catch(Exception e){throw new RuntimeException(e);}});View root=search.getWindow().getDecorView();EditText query=null;for(View v:views(root))if(v instanceof EditText){query=(EditText)v;break;}check(query!=null,"search input exists");final EditText input=query;ui(()->{input.setText("Alpha");button(root,t(music,"music_search_apply")).performClick();});pause();ui(()->button(root,t(music,"music_search_select_matches")).performClick());check(selected.containsAll(Arrays.asList("previous","content://qa/1","content://qa/2"))&&!selected.contains("content://qa/3"),"select all includes collapsed matches and keeps previous selection");
  ui(()->{for(View v:views(root))if(v instanceof Button&&Boolean.FALSE.equals(v.getTag())){v.performClick();break;}});pause();List<CheckBox> boxes=new ArrayList<>();for(View v:views(root))if(v instanceof CheckBox)boxes.add((CheckBox)v);check(boxes.size()==2,"expanded results have checkboxes");check(boxes.get(0).isChecked()&&boxes.get(1).isChecked(),"matching rows checked");ui(()->boxes.get(0).setChecked(false));check(selected.size()==2,"individual result deselection updates shared set");ui(()->button(root,"Alpha one").performClick());pause();check(edited.get()==1,"song name opens metadata editor");
  ui(()->button(root,t(music,"music_search_select_matches")).performClick());check(!selected.contains("content://qa/1")&&selected.contains("content://qa/2"),"edited title re-evaluates search matches");ui(()->button(root,t(music,"music_search_back")).performClick());check(returned.get()==1,"return refresh callback fires once");check(selected.contains("previous")&&selected.contains("content://qa/2"),"selection retained on return");search=null;
  Class<?> progressType=Class.forName("org.daidai.modules.music.MusicImportProgress",true,cl);Constructor<?> pc=progressType.getDeclaredConstructor(Activity.class);pc.setAccessible(true);AtomicReference<Object> progress=new AtomicReference<>();ui(()->{try{progress.set(pc.newInstance(music));}catch(Exception e){throw new RuntimeException(e);}});call(progress.get(),"file",new Class[]{String.class,int.class,int.class},"track-024.mp3",24,600);pause();Object pd=field(progress.get(),"dialog");boolean filename=false;for(View v:views(((Dialog)pd).getWindow().getDecorView()))if(v instanceof TextView&&((TextView)v).getText().toString().contains("track-024.mp3"))filename=true;check(filename,"import progress displays current filename");ui(()->((AlertDialog)pd).getButton(AlertDialog.BUTTON_NEGATIVE).performClick());check((Boolean)call(progress.get(),"cancelled",new Class[]{}),"cancel button requests import cancellation");check(!((Dialog)pd).isShowing(),"cancel closes progress dialog");
  result.putString("result","PASS: "+checks+" pre-3.0.0-3 interaction checks ("+lang+")");
 }catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));result.putString("result","FAIL: "+s);}finally{if(search!=null)ui(()->search.dismiss());if(music!=null)ui(()->music.finish());if(host!=null)ui(()->host.finish());finish(Activity.RESULT_OK,result);}}
}
